create table public.supplier_availability_offers(id uuid primary key default gen_random_uuid(),booking_id uuid not null references public.bookings(id) on delete cascade,supplier_id uuid not null references public.suppliers(id),availability text not null check(availability in('available','waitlist','unavailable')),net_rate numeric check(net_rate is null or net_rate>=0),currency text not null default 'AED' check(char_length(currency)=3),valid_until timestamptz,supplier_reference text,conditions text,decision text not null default 'pending' check(decision in('pending','selected','rejected','expired')),checked_by uuid references auth.users(id),checked_at timestamptz not null default now(),decided_by uuid references auth.users(id),decided_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.supplier_availability_offers enable row level security;revoke all on public.supplier_availability_offers from anon,authenticated;grant all on public.supplier_availability_offers to service_role;
create index supplier_availability_booking_idx on public.supplier_availability_offers(booking_id,created_at desc);
create or replace function public.record_supplier_availability(p_booking_id uuid,p_supplier_name text,p_availability text,p_net_rate numeric,p_currency text,p_valid_until timestamptz,p_supplier_reference text,p_conditions text) returns uuid language plpgsql security definer set search_path='public' as $function$ declare s public.suppliers%rowtype;v_id uuid;v_norm text;begin if auth.uid() is null then raise exception 'Authentication required';end if;if not public.has_staff_permission('edit_bookings') then raise exception 'Permission denied';end if;if p_availability not in('available','waitlist','unavailable') then raise exception 'Invalid availability';end if;if p_availability='available' and(p_net_rate is null or p_valid_until is null) then raise exception 'Available offers require net rate and validity';end if;if char_length(trim(coalesce(p_conditions,'')))<10 then raise exception 'Supplier conditions must be at least 10 characters';end if;if not exists(select 1 from public.bookings where id=p_booking_id and archived_at is null) then raise exception 'Booking not found';end if;v_norm:=lower(regexp_replace(trim(p_supplier_name),'\s+',' ','g'));insert into public.suppliers(name,normalized_name,created_by) values(trim(p_supplier_name),v_norm,auth.uid()) on conflict(normalized_name) do update set name=excluded.name,updated_at=now() returning * into s;if s.status<>'active' then raise exception 'Supplier is not active';end if;insert into public.supplier_availability_offers(booking_id,supplier_id,availability,net_rate,currency,valid_until,supplier_reference,conditions,checked_by) values(p_booking_id,s.id,p_availability,p_net_rate,upper(coalesce(p_currency,'AED')),p_valid_until,nullif(trim(coalesce(p_supplier_reference,'')),''),trim(p_conditions),auth.uid()) returning id into v_id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata) values(auth.uid(),'supplier.availability_recorded','supplier_availability_offer',v_id,jsonb_build_object('booking_id',p_booking_id,'supplier_id',s.id,'availability',p_availability,'net_rate',p_net_rate,'valid_until',p_valid_until));return v_id;end;$function$;
create or replace function public.list_supplier_availability(p_booking_id uuid) returns jsonb language plpgsql security definer stable set search_path='public' as $function$ begin if auth.uid() is null or not public.has_staff_permission('view_supplier_cost') then raise exception 'Supplier cost permission required';end if;return coalesce((select jsonb_agg(jsonb_build_object('id',o.id,'supplier_name',s.name,'availability',o.availability,'net_rate',o.net_rate,'currency',o.currency,'valid_until',o.valid_until,'supplier_reference',o.supplier_reference,'conditions',o.conditions,'decision',case when o.decision='pending' and o.valid_until<now() then 'expired' else o.decision end,'checked_at',o.checked_at) order by o.created_at desc) from public.supplier_availability_offers o join public.suppliers s on s.id=o.supplier_id where o.booking_id=p_booking_id),'[]'::jsonb);end;$function$;
create or replace function public.select_supplier_availability(p_offer_id uuid) returns jsonb language plpgsql security definer set search_path='public' as $function$ declare o public.supplier_availability_offers%rowtype;s public.suppliers%rowtype;b public.bookings%rowtype;begin if auth.uid() is null then raise exception 'Authentication required';end if;perform public.require_recent_auth(1800);if not public.has_staff_permission('edit_bookings') then raise exception 'Permission denied';end if;select * into o from public.supplier_availability_offers where id=p_offer_id for update;if not found or o.decision<>'pending' then raise exception 'Pending supplier offer not found';end if;if o.availability<>'available' or o.net_rate is null then raise exception 'Only available priced offers can be selected';end if;if o.valid_until is null or o.valid_until<=now() then update public.supplier_availability_offers set decision='expired',updated_at=now() where id=o.id;raise exception 'Supplier offer has expired';end if;select * into s from public.suppliers where id=o.supplier_id for update;if s.status<>'active' then raise exception 'Supplier is not active';end if;select * into b from public.bookings where id=o.booking_id and archived_at is null for update;if not found then raise exception 'Booking not found';end if;update public.supplier_availability_offers set decision=case when id=o.id then 'selected' else 'rejected' end,decided_by=auth.uid(),decided_at=now(),updated_at=now() where booking_id=o.booking_id and decision='pending';update public.bookings set supplier_id=s.id,supplier_name=s.name,supplier_cost=o.net_rate,supplier_reference=coalesce(o.supplier_reference,supplier_reference),updated_at=now() where id=b.id;insert into public.audit_events(actor_user_id,event_type,entity_type,entity_id,metadata) values(auth.uid(),'supplier.availability_selected','supplier_availability_offer',o.id,jsonb_build_object('booking_id',b.id,'supplier_id',s.id,'net_rate',o.net_rate,'currency',o.currency,'valid_until',o.valid_until,'supplier_reference',o.supplier_reference));return jsonb_build_object('id',o.id,'decision','selected','booking_id',b.id,'supplier_cost',o.net_rate);end;$function$;
revoke execute on function public.record_supplier_availability(uuid,text,text,numeric,text,timestamptz,text,text) from public,anon;grant execute on function public.record_supplier_availability(uuid,text,text,numeric,text,timestamptz,text,text) to authenticated,service_role;
revoke execute on function public.list_supplier_availability(uuid) from public,anon;grant execute on function public.list_supplier_availability(uuid) to authenticated,service_role;
revoke execute on function public.select_supplier_availability(uuid) from public,anon;grant execute on function public.select_supplier_availability(uuid) to authenticated,service_role;
